AssistantMessageToolRequest(name='create', tool_call_id='tooluse_YKy6XFDuedt3Vu7RMmhCJI', arguments={'file_text': '// React-style component functions rendered to DOM

const options = [
  { value: "email", label: "Email", icon: "✉️" },
  { value: "sms", label: "SMS", icon: "💬" },
  { value: "push", label: "Push Notifications", icon: "🔔" },
];

function RadioOption({ value, label, icon, name }) {
  const id = `notif-${value}`;
  const el = document.createElement("label");
  el.className = "radio-label";
  el.htmlFor = id;
  el.innerHTML = `
    <input
      class="radio-input"
      type="radio"
      id="${id}"
      name="${name}"
      value="${value}"
      aria-label="${label}"
    />
    <span class="radio-text">${label}</span>
    <span class="radio-icon" aria-hidden="true">${icon}</span>
  `;
  return el;
}

function NotificationForm() {
  const form = document.createElement("form");
  form.className = "form";
  form.noValidate = true;
  form.setAttribute("aria-label", "Notification preferences form");

  // Form field wrapper
  const formField = document.createElement("fieldset");
  formField.className = "form-field radio-group";

  const legend = document.createElement("legend");
  legend.textContent = "How do you prefer to receive notifications?";
  formField.appendChild(legend);

  options.forEach(({ value, label, icon }) => {
    formField.appendChild(RadioOption({ value, label, icon, name: "notification" }));
  });

  form.appendChild(formField);

  // Submit button
  const submitBtn = document.createElement("button");
  submitBtn.type = "submit";
  submitBtn.className = "submit-btn";
  submitBtn.textContent = "Save Preference";

  form.appendChild(submitBtn);

  // Toast notification
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.setAttribute("role", "status");
  toast.setAttribute("aria-live", "polite");

  let toastTimer = null;

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const selected = form.querySelector('input[name="notification"]:checked');
    if (!selected) {
      const firstRadio = form.querySelector('input[name="notification"]');
      firstRadio && firstRadio.focus();
      formField.setAttribute("aria-describedby", "notif-error");
      let errorMsg = document.getElementById("notif-error");
      if (!errorMsg) {
        errorMsg = document.createElement("p");
        errorMsg.id = "notif-error";
        errorMsg.style.cssText = "color:#f87171;font-size:0.85rem;margin-top:-0.25rem;";
        errorMsg.textContent = "Please select a notification preference.";
        formField.after(errorMsg);
      }
      return;
    }

    const errorMsg = document.getElementById("notif-error");
    if (errorMsg) errorMsg.remove();
    formField.removeAttribute("aria-describedby");

    const chosenLabel = options.find((o) => o.value === selected.value).label;
    showToast(`Saved! You'll receive ${chosenLabel} notifications.`);
  });

  function showToast(message) {
    toast.textContent = message;
    toast.classList.add("visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove("visible"), 3500);
  }

  document.body.appendChild(toast);

  return form;
}

function App() {
  const page = document.createElement("div");
  page.className = "page";

  const card = document.createElement("div");
  card.className = "card";

  const title = document.createElement("h1");
  title.className = "card-title";
  title.textContent = "Preferences";

  const subtitle = document.createElement("p");
  subtitle.className = "card-subtitle";
  subtitle.textContent = "Customize how you stay in the loop.";

  card.appendChild(title);
  card.appendChild(subtitle);
  card.appendChild(NotificationForm());
  page.appendChild(card);
  return page;
}

document.getElementById("root").appendChild(App());
